    Bug 1925889 - Don't use nsIEditorSpellCheck to get personal dictionary words. r=mkmelin,babolivier


    `nsIEditorSpellCheck.GetPersonalDictionary` and `GetPersonalDictionaryWord` are used by
    comm-central only and both can replaced with `mozIPersonalDictionary.wordList`

    I would like to get rid of both nsIEditorSpellCheck methods, so I replace both with
    mozIPersonalDictionary in comm-central.

    Differential Revision: https://phabricator.services.mozilla.com/D226270

diff --git a/mail/components/compose/content/dialogs/EdDictionary.js b/mail/components/compose/content/dialogs/EdDictionary.js
index 151db67772e..29b97468fb8 100644
--- a/mail/components/compose/content/dialogs/EdDictionary.js
+++ b/mail/components/compose/content/dialogs/EdDictionary.js
@@ -104,22 +104,18 @@ function FillDictionaryList() {
   ClearListbox(gDialog.DictionaryList);

   // Get the list from the spell checker
-  gSpellChecker.GetPersonalDictionary();
+  const wordList = Cc[
+    "@mozilla.org/spellchecker/personaldictionary;1"
+  ].getService(Ci.mozIPersonalDictionary).wordList;

-  var haveList = false;
-
-  // Get words until an empty string is returned
-  do {
-    var word = gSpellChecker.GetPersonalDictionaryWord();
-    if (word != "") {
+  if (wordList.hasMore()) {
+    while (wordList.hasMore()) {
+      const word = wordList.getNext();
       gDialog.DictionaryList.appendItem(word, "");
-      haveList = true;
     }
-  } while (word != "");
-
-  // XXX: BUG 74467: If list is empty, it doesn't layout to full height correctly
-  //     (ignores "rows" attribute) (bug is latered, so we are fixing here for now)
-  if (!haveList) {
+  } else {
+    // XXX: BUG 74467: If list is empty, it doesn't layout to full height correctly
+    //     (ignores "rows" attribute) (bug is latered, so we are fixing here for now)
     gDialog.DictionaryList.appendItem("", "");
   }
